package com.primehr.learningdevelopment.delivery.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;
@Entity@Table(name="ld_offering_resource",uniqueConstraints=@UniqueConstraint(name="uk_ld_offering_resource",columnNames={"agency_id","offering_id","resource_person_id","resource_role"}))
public class LdOfferingResource extends RspAuditedEntity{public enum Role{LEAD_FACILITATOR,RESOURCE_PERSON,COORDINATOR,SUPPORT_STAFF}
 @Column(name="offering_id",nullable=false,length=36)private String offeringId;@Column(name="resource_person_id",nullable=false,length=36)private String resourcePersonId;@Enumerated(EnumType.STRING)@Column(name="resource_role",nullable=false,length=30)private Role role;@Column(name="person_code",nullable=false,length=80)private String personCode;@Column(name="person_source",nullable=false,length=20)private String personSource;@Column(name="employee_no",length=100)private String employeeNo;@Column(name="display_name",nullable=false,length=250)private String displayName;@Column(name="provider_id",length=36)private String providerId;@Column(length=2000)private String expertise;@Column(length=2000)private String credentials;@Column(name="resource_fingerprint",nullable=false,length=64)private String resourceFingerprint;@Column(name="display_order",nullable=false)private int displayOrder;protected LdOfferingResource(){}public LdOfferingResource(String agency,String offering,String resource,Role role,String code,String source,String employeeNo,String name,String provider,String expertise,String credentials,String fingerprint,int order){super(agency);offeringId=requiredText(offering,"offeringId");resourcePersonId=requiredText(resource,"resourcePersonId");this.role=java.util.Objects.requireNonNull(role);personCode=requiredText(code,"personCode");personSource=requiredText(source,"personSource");this.employeeNo=optionalText(employeeNo);displayName=requiredText(name,"displayName");providerId=optionalText(provider);this.expertise=optionalText(expertise);this.credentials=optionalText(credentials);resourceFingerprint=requiredText(fingerprint,"resourceFingerprint");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");displayOrder=order;}public String getOfferingId(){return offeringId;}public String getResourcePersonId(){return resourcePersonId;}public Role getRole(){return role;}public String getPersonCode(){return personCode;}public String getPersonSource(){return personSource;}public String getEmployeeNo(){return employeeNo;}public String getDisplayName(){return displayName;}public String getProviderId(){return providerId;}public String getExpertise(){return expertise;}public String getCredentials(){return credentials;}public String getResourceFingerprint(){return resourceFingerprint;}public int getDisplayOrder(){return displayOrder;}}
